entries[75273] = { ["name"] = "Smelly", ["text"] = "Quest Item\nUnique\n\"He lives up to his name.\"" }
entries[75274] = { ["name"] = "Zen Alchemist Stone", ["text"] = "Binds when picked up\nUnique-Equipped: Alchemist Stone (1)\nTrinket\n+ 6 Mastery\nEquip: When you heal or deal damage you have a chance to increase your Strength, Agility, or Intellect by 21 for 15 sec. Your highest stat is always chosen. (Proc chance: 35%, 55s cooldown)\nEquip: Increases the effect that healing and mana potions have on the wearer by 40%. This effect does not stack.\nRequires Pandaria Alchemy (1)\n\"Can be used for transmutations in place of a Philosopher's Stone.\"\nSell Price:" }
entries[75275] = { ["name"] = "Mushan Shoulder Steak", ["text"] = "Quest Item\n\"Dark, gamy, muscular meat, from the shoulder. It doesn't look terribly appetizing.\"" }
entries[75276] = { ["name"] = "Turtle Meat Scrap", ["text"] = "Quest Item\n\"Thickly marbled with fat. Smells a bit gamy.\"" }
entries[75525] = { ["name"] = "Alchemist's Flask", ["text"] = "Binds when picked up\nUse: Increases your Agility, Strength, or Intellect by 12 for 2 hrs. Your highest stat is always chosen.\n\nCounts as both a Battle and Guardian elixir. Effect persists through death.\n\nCannot be used at level 49 or higher.\nRequires Classic Alchemy (1)\n\"This potent flask is not consumed when used.\"" }
